// Calculate date ranges
const now = new Date();

// Yesterday range
const yesterday = new Date(now);
yesterday.setDate(yesterday.getDate() - 1);
yesterday.setHours(0, 0, 0, 0);

const yesterdayEnd = new Date(yesterday);
yesterdayEnd.setHours(23, 59, 59, 999);

// Stripe payouts typically arrive T+2, so check 3 days ago
const threeDaysAgo = new Date(now);
threeDaysAgo.setDate(threeDaysAgo.getDate() - 3);
threeDaysAgo.setHours(0, 0, 0, 0);

// Unix timestamps for Stripe API
const threeDaysAgoUnix = Math.floor(threeDaysAgo.getTime() / 1000);
const yesterdayEndUnix = Math.floor(yesterdayEnd.getTime() / 1000);

return [{
  json: {
    yesterday: yesterday.toISOString().split('T')[0],
    yesterdayEnd: yesterdayEnd.toISOString().split('T')[0],
    threeDaysAgo: threeDaysAgo.toISOString().split('T')[0],
    threeDaysAgoUnix,
    yesterdayEndUnix
  }
}];

