// Merge payout and transaction data
const stripeData = $('HTTP - Get Stripe Payouts').first()?.json || { data: [] };
const transactionItems = $('Notion - Get Transactions').all() || [];

const payouts = stripeData.data || [];
const transactions = transactionItems.map(item => item.json);

return [{
  json: {
    payouts,
    transactions,
    payoutCount: payouts.length,
    transactionCount: transactions.length
  }
}];

// Match Stripe payouts to Relay deposits
const data = $input.first().json;
const stripePayouts = data.payouts;
const relayDeposits = [...data.transactions];

const reconciliation = {
  matched: [],
  unmatchedPayouts: [],
  unmatchedDeposits: [...relayDeposits]
};

const matchTransaction = (payout, deposits) => {
  const payoutAmount = payout.amount / 100; // Convert cents
  const payoutDate = new Date(payout.arrival_date * 1000);

  // Try exact match first
  let match = deposits.find(deposit => {
    const depositAmount = deposit.properties?.Amount?.number || 0;
    const depositDateStr = deposit.properties?.Date?.date?.start;
    if (!depositDateStr) return false;

    const depositDate = new Date(depositDateStr);
    const dateDiff = Math.abs(depositDate - payoutDate);

    // Exact amount, within ±2 days
    return Math.abs(depositAmount - payoutAmount) < 0.01 &&
           dateDiff <= 2 * 24 * 60 * 60 * 1000;
  });

  // If no exact match, try fuzzy
  if (!match) {
    match = deposits.find(deposit => {
      const depositAmount = deposit.properties?.Amount?.number || 0;
      const depositDateStr = deposit.properties?.Date?.date?.start;
      if (!depositDateStr) return false;

      const depositDate = new Date(depositDateStr);
      const dateDiff = Math.abs(depositDate - payoutDate);

      // Within $10, within ±3 days
      return Math.abs(depositAmount - payoutAmount) <= 10 &&
             dateDiff <= 3 * 24 * 60 * 60 * 1000;
    });
  }

  return match;
};

const calculateConfidence = (payout, deposit) => {
  const payoutAmount = payout.amount / 100;
  const depositAmount = deposit.properties?.Amount?.number || 0;
  const payoutDate = new Date(payout.arrival_date * 1000);
  const depositDateStr = deposit.properties?.Date?.date?.start;
  const depositDate = depositDateStr ? new Date(depositDateStr) : new Date();

  let confidence = 0;

  // Amount matching
  const amountDiff = Math.abs(payoutAmount - depositAmount);
  if (amountDiff < 0.01) confidence += 50;
  else if (amountDiff <= 5) confidence += 40;
  else if (amountDiff <= 10) confidence += 30;

  // Date matching
  const dateDiff = Math.abs(payoutDate - depositDate) / (24 * 60 * 60 * 1000);
  if (dateDiff < 1) confidence += 50;
  else if (dateDiff <= 2) confidence += 40;
  else if (dateDiff <= 3) confidence += 30;

  return Math.round(confidence);
};

// Process each payout
for (const payout of stripePayouts) {
  const match = matchTransaction(payout, reconciliation.unmatchedDeposits);

  if (match) {
    const confidence = calculateConfidence(payout, match);
    reconciliation.matched.push({
      payout: {
        id: payout.id,
        amount: payout.amount / 100,
        arrivalDate: new Date(payout.arrival_date * 1000).toISOString().split('T')[0],
        status: payout.status
      },
      deposit: {
        id: match.id,
        amount: match.properties?.Amount?.number || 0,
        date: match.properties?.Date?.date?.start,
        title: match.properties?.Transactions?.title?.[0]?.plain_text || 'Unknown'
      },
      confidence
    });

    // Remove from unmatched
    const index = reconciliation.unmatchedDeposits.findIndex(d => d.id === match.id);
    if (index > -1) {
      reconciliation.unmatchedDeposits.splice(index, 1);
    }
  } else {
    const payoutAge = (Date.now() - payout.arrival_date * 1000) / (24 * 60 * 60 * 1000);
    reconciliation.unmatchedPayouts.push({
      id: payout.id,
      amount: payout.amount / 100,
      arrivalDate: new Date(payout.arrival_date * 1000).toISOString().split('T')[0],
      status: payout.status,
      daysOld: Math.round(payoutAge),
      isOld: payoutAge > 3
    });
  }
}

// Calculate totals
const matchedTotal = reconciliation.matched.reduce((sum, m) => sum + m.payout.amount, 0);
const unmatchedPayoutTotal = reconciliation.unmatchedPayouts.reduce((sum, p) => sum + p.amount, 0);
const unmatchedDepositTotal = reconciliation.unmatchedDeposits.reduce((sum, d) => 
  sum + (d.properties?.Amount?.number || 0), 0
);

return [{
  json: {
    reconciliation,
    summary: {
      matchedCount: reconciliation.matched.length,
      matchedTotal,
      unmatchedPayoutCount: reconciliation.unmatchedPayouts.length,
      unmatchedPayoutTotal,
      unmatchedDepositCount: reconciliation.unmatchedDeposits.length,
      unmatchedDepositTotal,
      hasOldUnmatched: reconciliation.unmatchedPayouts.some(p => p.isOld)
    }
  }
}];

// Create transaction records for matched payouts
const data = $input.first().json;
const matched = data.reconciliation.matched;

// Return items to create
return matched.map(m => ({
  json: {
    title: `Stripe Payout → Relay`,
    amount: m.payout.amount,
    date: m.payout.arrivalDate,
    payoutId: m.payout.id,
    confidence: m.confidence,
    notes: `Auto-reconciled. Stripe payout: ${m.payout.id}. Confidence: ${m.confidence}%`
  }
}));

// Create pending transactions for unmatched payouts
const data = $('Code - Reconcile').first().json;
const unmatched = data.reconciliation.unmatchedPayouts;

return unmatched.map(p => ({
  json: {
    title: `:warning: Unmatched Stripe Payout`,
    amount: p.amount,
    date: p.arrivalDate,
    payoutId: p.id,
    daysOld: p.daysOld,
    notes: `Stripe payout not yet detected in Relay. Payout ID: ${p.id}. Expected: ${p.arrivalDate}. Days since payout: ${p.daysOld}. Check manually if not received within 5 business days.`
  }
}));

// Format daily summary report
const data = $('Code - Reconcile').first().json;
const { summary, reconciliation } = data;

let message = `:moneybag: *Daily Reconciliation Report*\n\n`;

message += `:white_check_mark: *Matched:* ${summary.matchedCount} transfers ($${summary.matchedTotal.toFixed(2)})\n`;
message += `:warning: *Unmatched Stripe Payouts:* ${summary.unmatchedPayoutCount} ($${summary.unmatchedPayoutTotal.toFixed(2)})\n`;
message += `:warning: *Unmatched Relay Deposits:* ${summary.unmatchedDepositCount} ($${summary.unmatchedDepositTotal.toFixed(2)})\n\n`;

if (summary.hasOldUnmatched) {
  message += `:rotating_light: *Alert:* Some payouts are >3 days old and still unmatched. Manual review required.\n\n`;

  reconciliation.unmatchedPayouts.filter(p => p.isOld).forEach(p => {
    message += `• $${p.amount.toFixed(2)} - Payout ${p.id} (${p.daysOld} days old)\n`;
  });
  message += '\n';
}

message += `<https://notion.so|View Transactions in Notion>`;

return [{
  json: {
    message,
    summary
  }
}];

// Create review tasks for old unmatched payouts
const data = $('Code - Reconcile').first().json;
const oldUnmatched = data.reconciliation.unmatchedPayouts.filter(p => p.isOld);

return oldUnmatched.map(p => ({
  json: {
    title: `:mag: Missing Relay Deposit: $${p.amount.toFixed(2)}`,
    dueDate: new Date(Date.now() + 2 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    notes: `Stripe payout not found in Relay after ${p.daysOld} days.\n\nAmount: $${p.amount.toFixed(2)}\nPayout ID: ${p.id}\nExpected Date: ${p.arrivalDate}\n\nAction: Check Relay account manually for this deposit.`
  }
}));
